class CustomerAccount {
  constructor(private readonly id: string, private accounts: BankAccount[]) {}
  addMoney(amount: number, currency: Currency): void {
    if (this.accounts.every(a => !a.isForCurrency(currency))) throw new Error('no account for currency');
    this.accounts = this.accounts.map(a => a.isForCurrency(currency) ? a.addMoney(amount) : a);
  }
}
class BankAccount {
  constructor(private readonly id: string, private readonly currency: Currency, private balance: number) {}
  isForCurrency(c: Currency): boolean { return this.currency.isEqual(c); }
  addMoney(amount: number): BankAccount { return new BankAccount(this.id, this.currency, this.balance + amount); }
}
